// Search the whole site, in the browser : search.json is generated by Jekyll at
// every build (one per language), so there is no index to keep up to date.
(function () {
  const form = document.getElementById("search-form");
  const input = document.getElementById("search-input");
  const status = document.getElementById("search-status");
  const results = document.getElementById("search-results");
  if (!form || !input || !status || !results) return;

  const emptyMessage = status.textContent;
  let posts = null;

  // "maitrise" must find "maîtrise" : accents are removed on both sides.
  const fold = (text) =>
    text.toLowerCase().normalize("NFD").replace(/\p{Diacritic}/gu, "");

  function count(n) {
    if (n === 0) return form.dataset.none;
    if (n === 1) return form.dataset.one;
    return form.dataset.many.replace("{n}", n);
  }

  function show(query) {
    const words = fold(query).split(/\s+/).filter(Boolean);
    results.replaceChildren();
    if (words.length === 0 || posts === null) {
      status.textContent = emptyMessage;
      return;
    }
    const found = posts.filter((post) => {
      const haystack = fold(post.title + " " + post.excerpt + " " + post.text);
      return words.every((word) => haystack.includes(word));
    });
    status.textContent = count(found.length);
    found.forEach((post) => {
      const card = document.createElement("div");
      card.className = "card-container card search-result";

      // Same card as the section pages : logo, section, title, summary.
      if (post.image) {
        const picture = document.createElement("img");
        picture.src = post.image;
        picture.alt = post.imageAlt || "";
        picture.title = post.imageAlt || "";
        picture.loading = "lazy";
        picture.className = "card-pic";
        card.appendChild(picture);
      }

      const section = document.createElement("p");
      section.className = "search-result-section";
      section.textContent = post.section + " — " + post.date;

      const title = document.createElement("h3");
      title.className = "card-title";
      const link = document.createElement("a");
      link.href = post.url;
      link.textContent = post.title;
      title.appendChild(link);

      const excerpt = document.createElement("p");
      excerpt.className = "card-details";
      excerpt.textContent = post.excerpt;

      card.append(section, title, excerpt);
      results.appendChild(card);
    });
  }

  function search() {
    const query = input.value.trim();
    // The query stays in the URL, so the link can be shared or bookmarked.
    const url = new URL(window.location.href);
    if (query) url.searchParams.set("q", query);
    else url.searchParams.delete("q");
    window.history.replaceState(null, "", url);
    show(query);
  }

  form.addEventListener("submit", (event) => event.preventDefault());
  input.addEventListener("input", search);

  const indexUrl = new URL(form.dataset.index, document.baseURI);
  fetch(indexUrl)
    .then((response) => response.json())
    .then((data) => {
      posts = data;
      const query = new URL(window.location.href).searchParams.get("q");
      if (query) input.value = query;
      show(input.value.trim());
    })
    .catch(() => {
      status.textContent = form.dataset.none;
    });

  input.focus();
})();
